import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.vLhlLNVn.js";const n="/assets/zaehlerstand-angleichen.DGfpZgVs.png",t="/assets/einstellungen-startwerte.BcWkm-3Q.png",s="/assets/zaehler-getauscht.IRuWhJKU.png",v=JSON.parse('{"title":"Correcting meter readings and replacing meters","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/02.zaehlerstaende-korrigieren.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","filePath":"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","lastUpdated":null}'),d={name:"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md"};function l(h,e,u,c,g,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="correcting-meter-readings-and-replacing-meters" tabindex="-1">Correcting meter readings and replacing meters <a class="header-anchor" href="#correcting-meter-readings-and-replacing-meters" aria-label="Permalink to &quot;Correcting meter readings and replacing meters&quot;">​</a></h1><p><a id="correct-wrong-too-high-negative"></a></p><h2 id="how-do-i-correct-wrong-too-high-or-negative-values-after-a-reset" tabindex="-1">How do I correct wrong, too high or negative values after a reset? <a class="header-anchor" href="#how-do-i-correct-wrong-too-high-or-negative-values-after-a-reset" aria-label="Permalink to &quot;How do I correct wrong, too high or negative values after a reset?&quot;">​</a></h2><p>With the source&#39;s &quot;Align meter reading&quot; action. You enter the reading your meter shows right now, and SourceAnalytix adjusts the total immediately, without a restart.</p><ol><li>In the instance settings, open the source on the &quot;Overview&quot; tab.</li><li>Under &quot;Actions&quot;, choose &quot;Align meter reading&quot;.</li><li>Enter the reading you took under &quot;What does your meter show now?&quot;.</li><li>Check the preview with the old and new total and click &quot;⚡ Align&quot;.</li></ol><p><img src="'+n+'" alt="The &quot;Align meter reading&quot; dialog with preview"></p><p>The action shifts the start values along with the total. A wrong jump that is already in today&#39;s or this month&#39;s consumption therefore stays. You remove it via the <a href="#values-negative-after-entering-start">start values</a>.</p><h3 id="repairing-costs" tabindex="-1">Repairing costs <a class="header-anchor" href="#repairing-costs" aria-label="Permalink to &quot;Repairing costs&quot;">​</a></h3><p>Costs are booked with every value, so a wrong jump is in the costs too. Afterwards, choose &quot;Recalculate costs from date&quot; with the day the error began. SourceAnalytix recalculates the costs with the price history; consumption stays the same.</p><h3 id="yesterday-and-older-periods" tabindex="-1">Yesterday and older periods <a class="header-anchor" href="#yesterday-and-older-periods" aria-label="Permalink to &quot;Yesterday and older periods&quot;">​</a></h3><p>Aligning does not recalculate closed periods such as yesterday, last month or the archive under <code>&lt;year&gt;</code>. If you correct before midnight, the error stays limited to today. Change older values and values in a history such as InfluxDB by hand.</p><p><strong>See also:</strong> <a href="#replaced-meter-device-avoid-negative">Meter or device swapped</a> · <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Previous periods</a></p><p><a id="values-negative-after-entering-start"></a></p><h2 id="why-are-my-values-negative-after-i-entered-start-values" tabindex="-1">Why are my values negative after I entered start values? <a class="header-anchor" href="#why-are-my-values-negative-after-i-entered-start-values" aria-label="Permalink to &quot;Why are my values negative after I entered start values?&quot;">​</a></h2><p>A start value is greater than the total. Consumption is total minus start value and then turns negative. The settings page no longer accepts such values, but they come from old entries or scripts.</p><table tabindex="0"><thead><tr><th>Entered</th><th>Result</th><th>Correct</th></tr></thead><tbody><tr><td>the period&#39;s consumption instead of a meter reading</td><td>almost the whole meter reading shows up as consumption</td><td>the reading at the start of the period</td></tr><tr><td>reading in Wh, price uses kWh</td><td>strongly negative</td><td>the value in kWh</td></tr><tr><td>the device value instead of the total</td><td>too high or negative</td><td>the source&#39;s &quot;Total&quot; as the reference</td></tr><tr><td>&quot;Month&quot; or &quot;Year&quot; above &quot;Day&quot;</td><td>the longer period turns negative</td><td>&quot;Day&quot; is the largest start value</td></tr></tbody></table><h3 id="correcting-the-start-values" tabindex="-1">Correcting the start values <a class="header-anchor" href="#correcting-the-start-values" aria-label="Permalink to &quot;Correcting the start values&quot;">​</a></h3><ol><li>Open the source. The &quot;Total&quot; is at the very top.</li><li>Under &quot;Settings&quot; › &quot;Start values&quot;, enter the reading at the start of each period. If you don&#39;t know it, empty the field; the period then counts from now.</li><li>Click &quot;⚡ Apply&quot;. If a value doesn&#39;t fit, the field shows an error and the button stays locked.</li></ol><p><img src="'+t+'" alt="The source&#39;s &quot;Settings&quot; area with &quot;Start values&quot; and &quot;For experts&quot; expanded"></p><p>Start values only apply until the next period rollover. If the total itself is wrong, use <a href="#correct-wrong-too-high-negative">Align meter reading</a>.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Values far too high or negative</a></p><p><a id="replaced-meter-device-avoid-negative"></a></p><h2 id="i-replaced-a-meter-or-device-how-do-i-avoid-negative-values" tabindex="-1">I replaced a meter or device: how do I avoid negative values? <a class="header-anchor" href="#i-replaced-a-meter-or-device-how-do-i-avoid-negative-values" aria-label="Permalink to &quot;I replaced a meter or device: how do I avoid negative values?&quot;">​</a></h2><p>With the &quot;Meter swapped&quot; action, ideally before the new meter delivers its first value. If the new meter starts at 0 and reset detection is on, SourceAnalytix keeps counting even without the action.</p><ol><li>Open the source and choose &quot;Meter swapped&quot; under &quot;Actions&quot;.</li><li>Enter the final reading of the old meter, the starting reading of the new one and the date.</li><li>Check the preview and click &quot;⚡ Apply swap&quot;. The total continues from the old final reading.</li></ol><p><img src="'+s+'" alt="The &quot;Meter swapped&quot; dialog with old final reading, new starting reading and date"></p><p>If the new meter has already delivered values and the total has jumped, use &quot;Align meter reading&quot; and recalculate the costs, see <a href="#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><h3 id="new-device-with-a-new-datapoint" tabindex="-1">New device with a new datapoint <a class="header-anchor" href="#new-device-with-a-new-datapoint" aria-label="Permalink to &quot;New device with a new datapoint&quot;">​</a></h3><p>A new datapoint, say a new Shelly, would be a new source. An alias avoids that: activate SourceAnalytix on an alias (for example under <code>alias.0</code>) and, when swapping, only point its target to the new device. Folders and total stay.</p><p><strong>See also:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean?</a> · <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name, alias and output ID</a></p><p><a id="meter-restarts-after-power-loss"></a></p><h2 id="my-meter-restarts-at-0-after-a-power-failure-or-every-day-what-do-i-set" tabindex="-1">My meter restarts at 0 after a power failure or every day: what do I set? <a class="header-anchor" href="#my-meter-restarts-at-0-after-a-power-failure-or-every-day-what-do-i-set" aria-label="Permalink to &quot;My meter restarts at 0 after a power failure or every day: what do I set?&quot;">​</a></h2><p>Turn on &quot;Reset detection&quot; and set the threshold lower than the amount the meter drops by on a restart. SourceAnalytix then keeps counting on top of the old total. For Shelly and Tasmota, the wizard already suggests reset detection.</p><ol><li>Open the source and set &quot;Reset detection&quot; under &quot;Settings&quot;.</li><li>Check the &quot;Reset detection threshold&quot; under &quot;For experts&quot;. It is in the unit of the price definition. <ul><li>Meter that drops to 0 on a power failure: the default of 1 fits.</li><li>Daily counter: lower than your smallest daily consumption, for example 0.1 kWh.</li><li>Small units such as m³: for example 0.1 m³.</li></ul></li><li>Click &quot;⚡ Apply&quot;.</li></ol><p><img src="'+t+'" alt="The &quot;Settings&quot; area with &quot;Reset detection&quot; and &quot;Reset detection threshold&quot; under &quot;For experts&quot;"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If the meter drops by less than the threshold, this counts as measurement jitter, and SourceAnalytix ignores new values until they exceed the old reading. With a daily counter and a threshold that is too large, part of the new day is lost this way.</p></div><p>If a source without reset detection drops to 0, the &quot;Problems&quot; tab shows &quot;Meter drops to 0, reset detection is off&quot; with &quot;⚡ Switch on&quot;. If there is a total counter next to the daily counter, use that one instead.</p><p><strong>See also:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean?</a> · <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Threshold and turning off reset detection</a></p><p><a id="apply-real-meter-reading-cumulativereading"></a></p><h2 id="how-do-i-apply-my-real-meter-reading-cumulativereading-raw-object" tabindex="-1">How do I apply my real meter reading (cumulativeReading, RAW object)? <a class="header-anchor" href="#how-do-i-apply-my-real-meter-reading-cumulativereading-raw-object" aria-label="Permalink to &quot;How do I apply my real meter reading (cumulativeReading, RAW object)?&quot;">​</a></h2><p>With &quot;Align meter reading&quot;, as described under <a href="#correct-wrong-too-high-negative">Correcting wrong values</a>. You don&#39;t need to edit any object for this. If your device already shows the real reading, say via an optical reading head, there is nothing to do.</p><p>Changing only the <code>cumulativeReading</code> state does not stick. The total is always device value plus offset, and the next value recalculates it. The action sets both to match each other.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">What is cumulativeReading?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">The terms</a></p>',43)])])}const f=a(d,[["render",l]]);export{v as __pageData,f as default};
